// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AIPromptTemplate) predicate.AIPromptTemplate {
	return predicate.AIPromptTemplate(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AIPromptTemplate) predicate.AIPromptTemplate {
	return predicate.AIPromptTemplate(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AIPromptTemplate) predicate.AIPromptTemplate {
	return predicate.AIPromptTemplate(sql.NotPredicates(p))
}
